import string

BASE36 = string.digits + string.ascii_uppercase  # '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_encode(n: int, width: int) -> str:
    """Encode integer n as a zero-padded base36 string of the given width."""
    chars = []
    for _ in range(width):
        chars.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(chars))


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def get_last_id(filename: str) -> str:
    """Return the last non-empty line from filename."""
    with open(filename) as f:
        lines = f.readlines()
    for line in reversed(lines):
        stripped = line.strip()
        if stripped:
            return stripped
    return ''


def next_id(current: str) -> str:
    """Given an id like 'ORD-243G', return the next sequential id."""
    prefix = current[:4]  # 'ORD-'
    suffix = current[4:]  # 4-character base36 string
    num = base36_decode(suffix)
    num += 1
    new_suffix = base36_encode(num, len(suffix))
    return prefix + new_suffix


if __name__ == '__main__':
    last = get_last_id('ids.txt')
    if last:
        print(next_id(last))
    else:
        print('ORD-0000')

