"""Print the next order id to stdout.

Order ids have the form ORD- followed by four base36 characters.
Reads ids.txt (one id per line, most recent last) and increments
the last id by one in base36.
"""

import sys

BASE36_DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer (case-insensitive)."""
    return int(s, 36)


def base36_encode(n: int) -> str:
    """Encode an integer to uppercase base36."""
    if n == 0:
        return "0"
    digits = []
    while n:
        digits.append(BASE36_DIGITS[n % 36])
        n //= 36
    return "".join(reversed(digits))


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    # Find the last non-empty line
    last_id = None
    for line in reversed(lines):
        stripped = line.strip()
        if stripped:
            last_id = stripped
            break

    if last_id is None:
        print("Error: ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Error: unexpected id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]  # four characters after ORD-
    try:
        current = base36_decode(suffix)
    except ValueError:
        print(f"Error: invalid base36 suffix: {suffix!r}", file=sys.stderr)
        sys.exit(1)

    next_val = current + 1
    next_suffix = base36_encode(next_val).zfill(4).upper()
    next_id = f"ORD-{next_suffix}"
    sys.stdout.write(next_id + "\n")


if __name__ == "__main__":
    main()

