    """Encode a non-negative integer as a base-36 string."""
    if n == 0:
        return "0"
    digits: list[str] = []
    while n:
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def main() -> None:
    ids_file = Path("ids.txt")
    if not ids_file.exists():
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    lines = [line.strip() for line in ids_file.read_text().splitlines() if line.strip()]

    if not lines:
        next_num = 0
    else:
        last_id = lines[-1]
        try:
            suffix = last_id.split("-", 1)[1]
        except IndexError:
            print(f"Invalid id format: {last_id!r}", file=sys.stderr)
            sys.exit(1)
        next_num = int(suffix, 36) + 1

    next_suffix = to_base36(next_num).zfill(4).upper()
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

